import Foundation

/// Les données embarquées et les combattants du prototype.
enum Catalogue {
    static let elements: [ElementChimique] = charger("elements")
    static let paysAfrique: [Pays] = charger("pays_afrique")
    /// Questions des combattants « à fiche », générées par `outils/fiches.py`.
    static let fiches: [String: FicheSpecialite] = {
        let liste: [FicheSpecialite] = charger("fiches")
        return Dictionary(uniqueKeysWithValues: liste.map { ($0.id, $0) })
    }()

    /// Un combattant commun dont les questions viennent d'une fiche.
    private static func aFiche(id: String, nom: String, style: String, familleStyle: FamilleStyle,
                               specialite: String, famille: String, domaine: String, fiche: String,
                               apparence: String, questions: String,
                               rarete: Rarete = .commun) -> ModeleCombattant {
        guard let donnees = fiches[fiche] else { fatalError("Fiche « \(fiche) » introuvable dans fiches.json") }
        let spec = Specialite(id: fiche, nom: specialite, famille: famille, domaine: domaine)
        let rare = rarete == .rare
        return ModeleCombattant(id: id, nom: nom, style: style, familleStyle: familleStyle,
                                specialite: spec, rarete: rarete,
                                pvMax: rare ? 110 : 100, attaque: rare ? 54 : 50, defense: rare ? 4 : 0, difficulte: 2,
                                apparence: apparence, questions: questions,
                                generateur: GenerateurFiche(specialite: spec, fiche: donnees))
    }

    /// Un combattant commun dont les questions viennent d'un générateur (calcul, éléments…).
    private static func aGenerateur(id: String, nom: String, style: String, familleStyle: FamilleStyle,
                                    specialite: String, famille: String, domaine: String, idSpecialite: String,
                                    difficulte: Int, apparence: String, questions: String,
                                    generateur: (Specialite) -> any GenerateurQuestions) -> ModeleCombattant {
        let spec = Specialite(id: idSpecialite, nom: specialite, famille: famille, domaine: domaine)
        return ModeleCombattant(id: id, nom: nom, style: style, familleStyle: familleStyle,
                                specialite: spec, rarete: .commun,
                                pvMax: 100, attaque: 50, defense: 0, difficulte: difficulte,
                                apparence: apparence, questions: questions,
                                generateur: generateur(spec))
    }

    /// Éléments d'une famille du tableau, par numéro atomique.
    private static func elementsNumeros(_ numeros: [Int]) -> [ElementChimique] {
        elements.filter { numeros.contains($0.numero) }
    }

    /// Questions sur les éléments (nom, symbole, numéro) complétées par une fiche de culture.
    private static func elementsEtFiche(_ specialite: Specialite, selection: [ElementChimique],
                                        difficulte: Int, fiche: String) -> GenerateurMixte {
        guard let donnees = fiches[fiche] else { fatalError("Fiche « \(fiche) » introuvable dans fiches.json") }
        let formes: [GenerateurElements.Forme] = [.nomDuSymbole, .symboleDuNom, .numeroAtomique]
        let elementsTires = selection.filter { $0.notoriete <= difficulte + 1 }
        return GenerateurMixte(parties: [
            .init(generateur: GenerateurElements(specialite: specialite, selection: selection,
                                                 tous: elements, formes: formes),
                  poids: (elementsTires.isEmpty ? selection : elementsTires).count * formes.count),
            .init(generateur: GenerateurFiche(specialite: specialite, fiche: donnees),
                  poids: donnees.nombreDeQuestions),
        ])
    }

    private static func charger<T: Decodable>(_ nom: String) -> [T] {
        guard let url = Bundle.module.url(forResource: nom, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let liste = try? JSONDecoder().decode([T].self, from: data) else {
            fatalError("\(nom).json introuvable ou illisible")
        }
        return liste
    }

